<?phpsession_start();require_once "db.php";$message = "";$messageType = "";if (empty($_SESSION['csrf_token'])) {    $_SESSION['csrf_token'] = bin2hex(random_bytes(32));}if ($_SERVER["REQUEST_METHOD"] === "POST") {    $name = trim($_POST['teacher_name'] ?? '');    $employee = strtoupper(trim($_POST['employee_id'] ?? ''));    $department = trim($_POST['department'] ?? '');    $email = strtolower(trim($_POST['email'] ?? ''));    $password = $_POST['password'] ?? '';    $confirm = $_POST['confirm_password'] ?? '';    if (!hash_equals(        $_SESSION['csrf_token'],        $_POST['csrf_token'] ?? ''    )) {        $message = "Invalid request. Refresh the page.";        $messageType = "error";    } elseif (        $name === '' ||        $employee === '' ||        $department === '' ||        !filter_var($email, FILTER_VALIDATE_EMAIL)    ) {        $message = "Please fill all details correctly.";        $messageType = "error";    } elseif ($password !== $confirm) {        $message = "Passwords do not match.";        $messageType = "error";    } elseif (strlen($password) < 8) {        $message = "Password must contain 8 characters.";        $messageType = "error";    } else {        $check = pg_query_params(            $conn,            "SELECT teacher_id FROM teachers             WHERE LOWER(email) = $1             OR employee_id = $2",            [$email, $employee]        );        if (!$check) {            $message = "Database error.";            $messageType = "error";        } elseif (pg_num_rows($check) > 0) {            $message = "Email or Employee ID already exists.";            $messageType = "error";        } else {            $hashedPassword = password_hash(                $password,                PASSWORD_DEFAULT            );            $sql = "INSERT INTO teachers            (                teacher_name,                employee_id,                department,                email,                password,                status            )            VALUES ($1,$2,$3,$4,$5,'pending')            RETURNING teacher_id";            $result = pg_query_params(                $conn,                $sql,                [                    $name,                    $employee,                    $department,                    $email,                    $hashedPassword                ]            );            if ($result) {                $message = "Registration submitted successfully! Wait for Admin approval.";                $messageType = "success";                $_SESSION['csrf_token'] =                    bin2hex(random_bytes(32));            } else {                $message = "Registration failed. Check database settings.";                $messageType = "error";            }        }    }}?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport"content="width=device-width, initial-scale=1.0"><title>SmartAttend - Register</title><style>* {    margin: 0;    padding: 0;    box-sizing: border-box;    font-family: Arial, sans-serif;}body {    background: #ffffff;    color: #202b45;    min-height: 100vh;}.container {    max-width: 680px;    margin: 0 auto;    padding: 45px 25px;}.top-text {    color: #9299a8;    font-size: 14px;    font-weight: bold;    letter-spacing: 3px;    margin-bottom: 35px;}h1 {    font-size: 40px;    margin-bottom: 20px;    letter-spacing: -1px;}.subtitle {    color: #9299a8;    font-size: 19px;    line-height: 1.6;    margin-bottom: 50px;}.tabs {    display: flex;    background: #f0f1f6;    padding: 7px;    border-radius: 17px;    margin-bottom: 42px;}.tabs a {    width: 50%;    text-align: center;    padding: 19px;    text-decoration: none;    color: #818a9b;    font-size: 17px;    font-weight: bold;    border-radius: 13px;}.tabs .active {    background: white;    color: #293650;    box-shadow: 0 3px 12px rgba(0,0,0,0.08);}.account-title {    font-weight: bold;    color: #566174;    margin-bottom: 16px;}.account-types {    display: flex;    gap: 16px;    margin-bottom: 27px;}.account-types button {    width: 50%;    padding: 19px 10px;    border: 2px solid #e4e7ed;    background: white;    border-radius: 15px;    font-size: 17px;    color: #788292;    cursor: pointer;}.account-types .selected {    border-color: #8292eb;    background: #f2f3ff;    color: #5264bb;}label {    display: block;    font-weight: bold;    color: #566174;    margin-bottom: 13px;    margin-top: 26px;}input {    width: 100%;    padding: 19px 22px;    border: 2px solid #e3e6eb;    border-radius: 15px;    font-size: 17px;    outline: none;}input:focus {    border-color: #6675e8;}.password-box {    position: relative;}.password-box input {    padding-right: 75px;}.show-btn {    position: absolute;    right: 15px;    top: 50%;    transform: translateY(-50%);    border: none;    background: none;    color: #5264bb;    font-weight: bold;    cursor: pointer;}.submit-btn {    width: 100%;    padding: 20px;    background: #5367e8;    color: white;    border: none;    border-radius: 15px;    font-size: 18px;    font-weight: bold;    margin-top: 36px;    cursor: pointer;}.submit-btn:hover {    background: #4054d0;}.message {    padding: 15px;    border-radius: 10px;    margin-bottom: 20px;    line-height: 1.5;}.success {    background: #dcfce7;    color: #166534;}.error {    background: #fee2e2;    color: #991b1b;}.bottom-note {    margin-top: 45px;    color: #a0a6b1;    text-align: center;    font-size: 14px;}@media(max-width:600px) {    .container {        padding: 25px 22px;    }    h1 {        font-size: 34px;    }    .subtitle {        font-size: 17px;    }    .account-types button {        font-size: 15px;        padding: 17px 5px;    }    input {        padding: 17px;    }}</style></head><body><div class="container"><div class="top-text">JOIN YOUR CAMPUS</div><h1>Create an account</h1><p class="subtitle">Student and teacher accounts require administrator approval.</p><div class="tabs"><a href="index.php">Sign in</a><a href="register.php" class="active">Register</a></div><div class="account-title">Account type</div><div class="account-types"><button type="button"onclick="studentNotice()">? Student</button><button type="button" class="selected">? Teacher</button></div><?php if ($message !== "") { ?><div class="message <?php echo $messageType; ?>"><?php echo htmlspecialchars($message); ?></div><?php } ?><form method="POST"><input type="hidden"name="csrf_token"value="<?php echo htmlspecialchars($_SESSION['csrf_token']); ?>"><label>Full name</label><input type="text"name="teacher_name"placeholder="Your full name"required><label>Employee ID</label><input type="text"name="employee_id"placeholder="e.g. EMP001"required><label>Department</label><input type="text"name="department"placeholder="e.g. Computer Science"required><label>Email address</label><input type="email"name="email"placeholder="name@college.edu"required><label>Password</label><div class="password-box"><input type="password"id="password"name="password"placeholder="At least 8 characters"minlength="8"required><button type="button"class="show-btn"onclick="togglePassword()">Show</button></div><label>Confirm Password</label><input type="password"name="confirm_password"placeholder="Confirm your password"minlength="8"required><button type="submit" class="submit-btn">Submit registration</button></form><div class="bottom-note">?? Protected access · Admin approval required for new accounts</div></div><script>function togglePassword() {    let password = document.getElementById("password");    let button = document.querySelector(".show-btn");    if (password.type === "password") {        password.type = "text";        button.innerText = "Hide";    } else {        password.type = "password";        button.innerText = "Show";    }}function studentNotice() {    alert("Student registration will be available soon.");}</script></body></html>